import{_ as e,o as a,c as s,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const m=JSON.parse('{"title":"4. 缓存层级: 从 L1 到 CDN 的全栈同构","description":"","frontmatter":{},"headers":[],"relativePath":"_meta/memory-hierarchy.md","filePath":"_meta/memory-hierarchy.md","lastUpdated":1788475713000}'),d={name:"_meta/memory-hierarchy.md"};function o(n,t,i,c,l,p){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="_4-缓存层级-从-l1-到-cdn-的全栈同构" tabindex="-1">4. 缓存层级: 从 L1 到 CDN 的全栈同构 <a class="header-anchor" href="#_4-缓存层级-从-l1-到-cdn-的全栈同构" aria-label="Permalink to &quot;4. 缓存层级: 从 L1 到 CDN 的全栈同构&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>一个硬件工程师、一个内核开发者、一个 DBA 和一个 SRE 坐在一起争论&quot;谁的 cache 最聪明&quot;。结果发现所有人的 cache 都是一个模板出来的: <strong>hit/miss 二分判定 → 按块取数据 → 替换策略淘汰 → 一致性协议同步多副本 → 写策略决定脏数据何时落下一层</strong>。从 1ns 的 L1 到 50ms 的 CDN edge，延迟跨越 7 个数量级，但<strong>抽象模型完全不变</strong>。整个计算机的体系结构是一部递归的 cache 层次模型——你学透一层，就学透了所有层。</p><hr><h2 id="一、全栈延迟光谱-一张表看尽所有-cache-层" tabindex="-1">一、全栈延迟光谱: 一张表看尽所有 cache 层 <a class="header-anchor" href="#一、全栈延迟光谱-一张表看尽所有-cache-层" aria-label="Permalink to &quot;一、全栈延迟光谱: 一张表看尽所有 cache 层&quot;">​</a></h2><p>先把这个宇宙摊开。从 CPU 管芯内到地球对面的 CDN POP，每一层都在玩同一个游戏: &quot;用空间换时间，用高一层的小容量低延迟，缓存下一层的大容量高延迟数据&quot;。</p><table tabindex="0"><thead><tr><th>层级</th><th>容量</th><th>延迟</th><th>单位块大小</th><th>替换策略</th><th>一致性协议</th><th>详述章节</th></tr></thead><tbody><tr><td>寄存器</td><td>~16 KB 全 CPU</td><td>&lt;1ns</td><td>8B (x86) / 16B (SIMD)</td><td>编译器分配 (graph coloring)</td><td>无需 (单消费者)</td><td><a href="./../computer-arch/isa-design">isa-design.md</a></td></tr><tr><td>L1 D-cache</td><td>48-128 KB</td><td>~1ns (4-5 cycle @ 4GHz)</td><td>64B line</td><td>PLRU / RRIP (硬件)</td><td>MESI/MOESI/MESIF</td><td><a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a></td></tr><tr><td>L2 cache</td><td>256KB-16MB</td><td>~4-16ns</td><td>64B line</td><td>PLRU / RRIP (硬件)</td><td>MESI/MOESI/MESIF</td><td><a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §三-五</td></tr><tr><td>L3 cache</td><td>4-96MB</td><td>~12-50ns</td><td>64B line</td><td>BRRIP / Adaptive (硬件)</td><td>Directory-based (硬件)</td><td><a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §七</td></tr><tr><td>TLB (L1/L2)</td><td>64-1536 项</td><td>1-7 cycle</td><td>4KB / 2MB / 1GB page</td><td>LRU (硬件)</td><td>TLB Shootdown (IPI)</td><td><a href="./../computer-arch/mmu-dma">mmu-dma.md</a> §3</td></tr><tr><td>3D V-Cache</td><td>额外 64MB L3</td><td>~40ns (+4 cycle penalty)</td><td>64B line</td><td>同 L3</td><td>同 L3</td><td><a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §十</td></tr><tr><td>DRAM (DDR5)</td><td>8-256GB</td><td>~80-100ns</td><td>64B (cache line fill) / 8Kb (row buffer)</td><td>无 (主存储; OS 换页时做)</td><td>无 (单 master: mem ctrl)</td><td><a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §八</td></tr><tr><td>HBM3e</td><td>24-36GB / stack</td><td>~50-80ns</td><td>64B / 1024-bit 宽通道</td><td>无 (同 DRAM)</td><td>无</td><td><a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §九</td></tr><tr><td>CXL Type-3 内存池</td><td>512GB-2TB</td><td>~250-350ns</td><td>64B / cache coherent</td><td>OS NUMA 调度</td><td>CXL.cache (MESI 扩展)</td><td><a href="./../computer-arch/interconnects">interconnects.md</a> §三</td></tr><tr><td>NVMe SSD</td><td>1-30TB</td><td>~50-100µs</td><td>4KB page</td><td>FTL firmware (vendor-specific)</td><td>无 (单 master)</td><td><a href="./../os/fs/filesystems">os/fs/filesystems.md</a></td></tr><tr><td>OS Page Cache</td><td>可用 DRAM 的 80-90%</td><td>DRAM hit (~100ns); miss 走 IO</td><td>4KB page</td><td>Linux: 双链表 LRU (active/inactive)</td><td>无 (单 OS instance)</td><td><a href="./../os/fs/inode-pagecache">os/fs/inode-pagecache.md</a></td></tr><tr><td>InnoDB Buffer Pool</td><td>可配 (典型 80% RAM)</td><td>DRAM hit (~100ns); miss 走 IO</td><td>16KB page (默认)</td><td>改进 LRU (midpoint insertion)</td><td>WAL + doublewrite (crash safety)</td><td><a href="./../system-design/storage/wal-lsm-btree">wal-lsm-btree.md</a></td></tr><tr><td>RocksDB Block Cache</td><td>可配 (典型 4-64GB)</td><td>DRAM hit; miss 走 SSTable</td><td>4-32KB data block</td><td>LRU / Clock (Hyper Clock Cache)</td><td>LSM compaction (tombstone)</td><td><a href="./../system-design/storage/wal-lsm-btree">wal-lsm-btree.md</a></td></tr><tr><td>进程内 Cache (Caffeine)</td><td>~1-8GB (per process)</td><td>~50-500ns</td><td>Object-level (variable)</td><td>W-TinyLFU (window + count-min sketch)</td><td>无 (多进程不共享, 最终一致性)</td><td><a href="./../system-design/cache/multilevel">multilevel.md</a></td></tr><tr><td>Redis LRU</td><td>~数 GB-百 GB (per cluster)</td><td>~0.5-2ms (网络 RTT)</td><td>Key-level (variable)</td><td>allkeys-lru / volatile-lru / LFU</td><td>主从复制 (async, eventual)</td><td><a href="./../system-design/cache/multilevel">multilevel.md</a></td></tr><tr><td>Memcached</td><td>~数 GB-百 GB (per pool)</td><td>~0.5-2ms</td><td>1MB slab class (per-page)</td><td>Per-slab LRU</td><td>无 (无复制, 无持久化)</td><td><a href="./../system-design/cache/multilevel">multilevel.md</a></td></tr><tr><td>CDN Edge Cache</td><td>~TB per POP</td><td>~5-50ms (从 edge 取); origin miss ~50-300ms</td><td>Object-level (HTTP cache)</td><td>LRU / 2Q / Hyperbolic (基于 cost)</td><td>Purge + TTL invalidation (push/purge)</td><td><a href="./../system-design/cache/multilevel">multilevel.md</a></td></tr><tr><td>远端网络 (RDMA)</td><td>跨机 DRAM</td><td>~1-5µs (IB) / ~5-10µs (RoCE)</td><td>MTU ~1.5KB / 4KB (RDMA)</td><td>远端内存管理 (pre-registered MR)</td><td>IOMMU 隔离 + 单边操作</td><td><a href="./../computer-arch/interconnects">interconnects.md</a> §五; <a href="./../distributed/replication/topologies">topologies.md</a></td></tr></tbody></table><p>这张表的核心信息: <strong>每一层往上走 1-2 个数量级延迟, 往下一层走 1-2 个数量级容量。每一层都有: 命中判定 (hit/miss)、按块传输 (block/line/page/object)、替换 (eviction)、一致性 (多副本同步)、写策略 (write-through / write-back)。</strong> 这五行是 cache 宇宙的&quot;基本力&quot;。</p><hr><h2 id="二、同构性证成-五个维度逐一展开" tabindex="-1">二、同构性证成: 五个维度逐一展开 <a class="header-anchor" href="#二、同构性证成-五个维度逐一展开" aria-label="Permalink to &quot;二、同构性证成: 五个维度逐一展开&quot;">​</a></h2><h3 id="_2-1-命中-缺失-从-tag-比较到-key-lookup" tabindex="-1">2.1 命中 / 缺失: 从 TAG 比较到 key lookup <a class="header-anchor" href="#_2-1-命中-缺失-从-tag-比较到-key-lookup" aria-label="Permalink to &quot;2.1 命中 / 缺失: 从 TAG 比较到 key lookup&quot;">​</a></h3><p>L1 cache 如何判断命中?——把地址拆成 <code>{tag, index, offset}</code>, 取 index 找到 set, 比较所有 way 的 tag 位是否匹配 (见 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §三)。这是纯硬件的 CAM/SRAM 并行比较, 一个 cycle 出结果。</p><p>Redis 如何判断命中?——客户端发 <code>GET user:12345</code>, Redis 对 <code>user:12345</code> 做 hash → 找到 slot → 在 dict 里 key lookup → 返回 value 或 <code>nil</code>。延迟从 1ns 变成 0.5ms, 但本质上还是同一个模式: <strong>用 key (地址/字符串) → 查目录 (index/slot) → 比较 tag/键 → 命中了拿数据, 没命中 report miss</strong>。</p><p>每次 L1 cache miss 触发一次 DRAM 访问 (见 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §二: tRCD + tCL + tRP ≈ 45ns 的 DRAM 随机读流程)。每次 Redis miss 触发一次 DB query → 网络 RTT → SQL parse → buffer pool lookup → IO (如果也不在 buffer pool 里)。抽象上这两个流程的形状完全一致: <strong>miss → 下一层按块取 → 填回本层 → 返回数据</strong>。</p><p>TLB 的命中判定是这个模式的又一实例: TLB 是一张极小的全相联/组相联 SRAM (见 <a href="./../computer-arch/mmu-dma">mmu-dma.md</a> §3.2), 以 <code>{VA, ASID/PCID}</code> 为 key, <code>{PA, permissions}</code> 为 value。TLB miss 触发硬件页表遍历 (page table walk)——逐级读 PML4E → PDPTE → PDE → PTE (见 <a href="./../computer-arch/mmu-dma">mmu-dma.md</a> §2.2), 每级一次 DRAM 随机读, 共 4 次 × 100ns = 400ns。这和一次&quot;Redis miss → 查 Postgres → 回填 Redis&quot;的流程在逻辑结构上完全没有区别——TLB 就是一个物理地址的 cache, 页表遍历就是 cache miss 的 penalty path。</p><h3 id="_2-2-替换策略-从-plru-到-w-tinylfu-的同构演化" tabindex="-1">2.2 替换策略: 从 PLRU 到 W-TinyLFU 的同构演化 <a class="header-anchor" href="#_2-2-替换策略-从-plru-到-w-tinylfu-的同构演化" aria-label="Permalink to &quot;2.2 替换策略: 从 PLRU 到 W-TinyLFU 的同构演化&quot;">​</a></h3><p>硬件 cache (<a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §五) 受限于硅面积和功耗预算, 只能在 PLRU、RRIP、BRRIP 等接近但非精确的 LRU 近似上做文章。L1 用简单的 PLRU (一个 per-set 的小状态机), L3 用 BRRIP (扫描行插入时直接给&quot;即将淘汰&quot;的优先级以保护常驻热数据)。</p><p>软件 cache 拿到了更充裕的算力预算, 于是可以在 Caffeine 里跑 W-TinyLFU——Window 小队列处理 burst access, Count-Min Sketch 做频率统计, SLRU 主队列根据频率 + 最近性做淘汰 (见 <a href="./../system-design/cache/multilevel">multilevel.md</a>)。这个算法比 BRRIP 聪明, 但它和 BRRIP 要解决的问题是同一个: <strong>&quot;怎么区分一次扫描 (永远不会再访问) 和真正的热点 (会反复访问)&quot;</strong>。硬件用 re-reference interval 预测, 软件用 count-min sketch 计数——手段不同, 问题同构。</p><p>Linux page cache (见 <a href="./../os/fs/inode-pagecache">os/fs/inode-pagecache.md</a> 和 <a href="./../os/memory/replacement">os/memory/replacement.md</a>) 用双链表 LRU: active list (刚被访问或访问过两次) 和 inactive list (上次访问距今较远)。当 inactive list 中的 page 被再次访问, 它 promote 进 active list。这实质上是 ARC (Adaptive Replacement Cache) 的一个简化版本: <strong>维护两个队列, 动态调整两者之间的平衡, 以自适应&quot;扫描&quot;和&quot;热点&quot;两种 workload</strong>。</p><p>InnoDB Buffer Pool (见 <a href="./../system-design/storage/wal-lsm-btree">wal-lsm-btree.md</a>) 也用了改进版 LRU: midpoint insertion——新读入的 page 不放在 LRU 头部, 而是放在 5/8 位置 (midpoint)。这样一次全表扫描不会把真正的热点全部挤出 LRU (扫描到的 page 从 midpoint 开始, 很快被淘汰; 反复访问的 page 自然晋升到头部)。这是 BRRIP 的软件版本: 扫描行以&quot;即将淘汰&quot;的起点入场, 避免污染热数据。</p><p>替换策略的同构: <strong>无论硬件 cache 还是软件 cache, 算法的核心矛盾都是&quot;保护热数据不被扫描冲走&quot;</strong>。硬件用 RRPV, 软件用 midpoint insertion / W-TinyLFU / ARC——本质都是给新进来的数据一个&quot;试用期&quot;, 只有证明自己是热的才能留下来。</p><h3 id="_2-3-一致性协议-mesi-↔-paxos-raft-的深层同构" tabindex="-1">2.3 一致性协议: MESI ↔ Paxos/Raft 的深层同构 <a class="header-anchor" href="#_2-3-一致性协议-mesi-↔-paxos-raft-的深层同构" aria-label="Permalink to &quot;2.3 一致性协议: MESI ↔ Paxos/Raft 的深层同构&quot;">​</a></h3><p>这是全章最核心的洞察。重新审视 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §六和 <a href="./../distributed/consensus/paxos">paxos.md</a> 之后, 你会发现 <strong>MESI 就是硬件尺度的 Paxos</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MESI (4 个 core 共享一个 cache line):</span></span>
<span class="line"><span>  - Core 0 有 line 在 Modified 状态 (dirty, exclusive owner)</span></span>
<span class="line"><span>  - Core 1 想读同一 line → 发 snoop 请求</span></span>
<span class="line"><span>  - Core 0 必须响应: 把脏数据转发给 Core 1 (或写回 DRAM), 自己降到 Shared</span></span>
<span class="line"><span>  - Core 2 想写同一 line → 发 RFO (Read For Ownership)</span></span>
<span class="line"><span>  - 总线广播 invalidate → 所有其他 core 的 Shared copy 失效 → Core 2 得到 Exclusive → 提升到 Modified</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Paxos (5 个节点对一个 log entry 达成共识):</span></span>
<span class="line"><span>  - Leader (Proposer) 有 proposal n, value v</span></span>
<span class="line"><span>  - Phase 1 (Prepare): 发 proposal number n 到 majority, 收集 promise (承诺不再接受 &lt;n 的 proposal)</span></span>
<span class="line"><span>  - Phase 2 (Accept): 让 majority accept (n, v)</span></span>
<span class="line"><span>  - 任何新的 Proposer 发起更高 n&#39; 的 Prepare → 必须从前一轮的 accepted value 中学习已决定的 v</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>同构点:</span></span>
<span class="line"><span>  - MESI 的 Modified → Exclusive 的&quot;写回/转发&quot; ≈ Paxos 的&quot;新 proposer 学习已 accepted 的 value&quot;</span></span>
<span class="line"><span>  - MESI 的 invalidate 广播 ≈ Paxos 的 Quorum overlap (任意两个 majority 必相交)</span></span>
<span class="line"><span>  - MESI 的 directory protocol (精确发送 invalidate 给持有者) ≈ Multi-Paxos 的&quot;只需要稳定 leader 与 followers 通信&quot;</span></span>
<span class="line"><span>  - MESI 的 MOESI Owned 状态 (转发脏数据但不写回 DRAM) ≈ Raft 的 leader 向 follower 复制 log entry, 然后 commit</span></span></code></pre></div><p>这两个协议的核心机制几乎逐行对应:</p><table tabindex="0"><thead><tr><th>概念</th><th>MESI (硬件)</th><th>Paxos/Raft (软件)</th></tr></thead><tbody><tr><td>状态机</td><td>4 状态: M/E/S/I → 5/6/7 状态 (MOESI/MESIF)</td><td>Follower/Candidate/Leader → log state machine</td></tr><tr><td>排他权获取</td><td>RFO (Read For Ownership) 总线事务</td><td>Leader election (RequestVote)</td></tr><tr><td>数据传播</td><td>Snoop 广播 / Directory 精确发送</td><td>Leader AppendEntries → followers</td></tr><tr><td>脏数据写回</td><td>eviction 时 write-back 到下一层</td><td>follower commit 后 ack leader</td></tr><tr><td>冲突解决</td><td>总线仲裁 (priority) / Directory 顺序化</td><td>Term number 单调递增 (高 term 胜)</td></tr><tr><td>共享态降级</td><td>Invalidate 广播 → 所有 S 变为 I</td><td>Leader 切换 → 旧 leader 降级为 follower</td></tr><tr><td>一致性边界</td><td>单个 cache coherence domain (socket/CCD)</td><td>单个 Raft group / Paxos instance</td></tr></tbody></table><p>同样的性质也体现在分布式缓存中: Redis 主从复制 (见 <a href="./../system-design/cache/multilevel">multilevel.md</a>) 是 MESI Shared 状态的软件化——主节点持有 writable copy (≈ Modified), 从节点持有 read-only copy (≈ Shared)。主节点写入后异步传播到从节点 → 这和 write-back cache 的&quot;先改本地, 延迟传播到下一层&quot;逻辑一致。CDN 的 purge/invalidation 机制 (见 <a href="./../system-design/cache/failure-modes">failure-modes.md</a>) 则是 MESI Invalidate 的全网版本: 源站更新了对象 → 发 PURGE 请求到所有边缘节点 → 边缘节点把旧副本标记为 invalid → 下一次请求触发 miss 回源。</p><p><strong>为什么分布式一致性算法的 paper 那么难读?</strong> 因为它在软件层重新发明了 MESI 已经在硬件层做过的事情——但多出了网络分区、消息丢失、时钟不可靠这些物理约束, 导致协议多了好几层复杂度。MESI 的通信介质是芯片内铜互联 (确定性延迟, 总线不丢包, 电压信号无歧义), Paxos 的通信介质是 UDP/IP 网络 (不确定性延迟, 丢包, 拜占庭行为可能)——<strong>同样是分布式一致性, 底下的信道的可靠性差异决定了上层协议的复杂度差异</strong>。</p><h3 id="_2-4-查找结构-tlb-→-页表-→-数据库索引" tabindex="-1">2.4 查找结构: TLB → 页表 → 数据库索引 <a class="header-anchor" href="#_2-4-查找结构-tlb-→-页表-→-数据库索引" aria-label="Permalink to &quot;2.4 查找结构: TLB → 页表 → 数据库索引&quot;">​</a></h3><p>这组同构更直接, 但也更容易被忽略。看 <a href="./../computer-arch/mmu-dma">mmu-dma.md</a> §1-3 和 <a href="./../os/memory/virtual-memory">os/memory/virtual-memory.md</a>, 再对比 <a href="./../system-design/storage/wal-lsm-btree">wal-lsm-btree.md</a> 的 B-tree 索引结构:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TLB          = 虚拟地址 → 物理地址 的 cache</span></span>
<span class="line"><span>页表         = 虚拟地址 → 物理地址 的完整映射表 (存在 DRAM 里)</span></span>
<span class="line"><span>B-tree 索引  = key → row location 的完整映射表 (存在磁盘上)</span></span></code></pre></div><p>TLB 对页表的关系, = Buffer Pool 对 B-tree 索引的关系。<strong>TLB 是页表的 cache, Buffer Pool 是 B-tree 索引的 cache。</strong> 一次 TLB miss 触发 page walk (4 次 DRAM 读, 见 <a href="./../computer-arch/mmu-dma">mmu-dma.md</a> §2), 一次 buffer pool miss 触发 B-tree 遍历 (从 root page 一路 seek 到 leaf page, 若干次 IO)。命中时都是 O(1) 的直接查找, miss 时都要走完整的索引遍历——然后<strong>把翻译结果 (PTE / leaf page) 缓存回高速结构中以备后用</strong>。</p><p>更大的同构: 即使是 DNS (域名 → IP) 也是一种 cache 层次——<code>/etc/hosts</code> 是 L1 (本地, 1µs), local DNS resolver cache 是 L2 (本机, ~1ms), upstream DNS 是 L3 (网络, ~10-50ms), 权威 DNS 是 origin (从 zone file 查, 最慢)。递归查询的流程和 TLB miss → page walk → 填回 TLB 的流程一模一样。</p><h3 id="_2-5-宽总线-vs-窄快速-hbm-nvlink-rdma-的同一模式" tabindex="-1">2.5 宽总线 vs 窄快速: HBM / NVLink / RDMA 的同一模式 <a class="header-anchor" href="#_2-5-宽总线-vs-窄快速-hbm-nvlink-rdma-的同一模式" aria-label="Permalink to &quot;2.5 宽总线 vs 窄快速: HBM / NVLink / RDMA 的同一模式&quot;">​</a></h3><p>从 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §九 (HBM3 的 1024-bit 宽总线 + TSV 堆叠) 到 <a href="./../computer-arch/interconnects">interconnects.md</a> §四 (NVLink 4 的 900 GB/s 点对点宽带) 再到 <a href="./../computer-arch/interconnects">interconnects.md</a> §五 (RDMA 的远程内存直接访问), 它们在解决同一个问题:<strong>延迟不能降, 就加宽通道, 用并行换吞吐</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HBM3:   1024-bit bus × 6.4 Gbps = 819 GB/s per stack</span></span>
<span class="line"><span>        TSV 堆叠 12 层 DRAM die → 物理距离 mm 级 → 延迟 ~50ns</span></span>
<span class="line"><span>        &quot;既然 DDR5 DIMM 的 64-bit 太窄, 我直接把 1000 根线铺过去&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NVLink 4: 50 GB/s per link × 18 links per H100 = 900 GB/s</span></span>
<span class="line"><span>        点对点专用链路 → 不共享, 不仲裁 → 延迟 ~100ns</span></span>
<span class="line"><span>        &quot;既然 PCIe x16 = 64 GB/s 不够, 我直接把 18 条独立链路放上去&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RDMA:    400 Gbps InfiniBand NDR = 50 GB/s per port</span></span>
<span class="line"><span>        单边操作绕过远端 CPU → 延迟 ~1µs</span></span>
<span class="line"><span>        &quot;既然 kernel TCP stack 延迟太大, 我让网卡 DMA 引擎直接读写远端 HBM&quot;</span></span></code></pre></div><p>这三个技术的共同模式可以抽象为:<strong>&quot;你感觉延迟高, 不是因为信道传输慢, 是因为串行化、协议栈、共享仲裁在吃掉你的时间。把通道变宽、把协议变薄、把仲裁去掉, 延迟自然降下来。&quot;</strong> HBM 用物理堆叠和极宽总线去掉 DDR DIMM 的封装/走线/仲裁延迟; NVLink 用专用点对点链路去掉 PCIe 树形拓扑的 switch 延迟; RDMA 用单边动词 (RDMA Write/Read) 去掉远端 CPU 中断 + 内核协议栈延迟。三者在不同尺度上, 实现的是同一个工程原则。</p><hr><h2 id="三、memory-wall-一个概念贯穿所有层级" tabindex="-1">三、Memory Wall: 一个概念贯穿所有层级 <a class="header-anchor" href="#三、memory-wall-一个概念贯穿所有层级" aria-label="Permalink to &quot;三、Memory Wall: 一个概念贯穿所有层级&quot;">​</a></h2><p>&quot;Memory Wall&quot;(Wulf &amp; McKee, 1995) 的原始含义是: <strong>CPU 算力每年增长 55%, 而 DRAM 延迟每年只改善 7%</strong>。25 年后, 这个趋势不仅没有收敛, 反而扩散到整个栈:</p><h3 id="每层-memory-wall-的表现" tabindex="-1">每层 Memory Wall 的表现 <a class="header-anchor" href="#每层-memory-wall-的表现" aria-label="Permalink to &quot;每层 Memory Wall 的表现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>计算侧</th><th>存储侧</th><th>Wall 表现</th></tr></thead><tbody><tr><td>GPU SM / Tensor Core</td><td>1979 TFLOPS (H100 FP8)</td><td>HBM3e 3.35 TB/s</td><td><strong>每 FLOP 只有 ~1.7 字节带宽</strong>。一个 matmul 如果数据重用不够, 算力根本吃不饱。</td></tr><tr><td>CPU core</td><td>5-6 IPC × 4GHz = ~20 B ops/s</td><td>DDR5 100 GB/s</td><td><strong>每操作 ~5 字节带宽</strong>。pointer chasing (链表/树/图遍历) 是 MLP=1 的串行 miss, 带宽被闲置。</td></tr><tr><td>数据库 scan</td><td>SIMD 扫描 64B/cycle</td><td>NVMe 7 GB/s</td><td><strong>PCIe 4.0 x4 = 7 GB/s。CPU 的 scan 速度是 NVMe 的 ~10 倍</strong>——列存压缩 + 下推 filter 就是为了&quot;不让 IO 成为瓶颈&quot;。</td></tr><tr><td>分布式训练</td><td>8 GPU × 1979 TFLOPS</td><td>NDR 400 Gbps = 50 GB/s per GPU</td><td><strong>跨节点 all-reduce 梯度同步的带宽只有 GPU 内部带宽的 1/70</strong>。TP 必须在 NVLink 域内, PP/DP 才跨 InfiniBand。</td></tr><tr><td>Redis 集群</td><td>单节点 100K QPS (单线程)</td><td>网络 10-25 Gbps = 1.25-3.125 GB/s</td><td><strong>算力充足但网络带宽是瓶颈</strong>——Redis 集群的规模上限由网卡带宽和延迟决定, 不是由 CPU 决定。</td></tr></tbody></table><h3 id="量化-wall-从参数看鸿沟" tabindex="-1">量化 Wall: 从参数看鸿沟 <a class="header-anchor" href="#量化-wall-从参数看鸿沟" aria-label="Permalink to &quot;量化 Wall: 从参数看鸿沟&quot;">​</a></h3><p>以 NVIDIA H100 (2022) 为例:</p><ul><li><strong>计算</strong>: 1979 TFLOPS (FP8) = 每秒 1.979 × 10^15 次乘加</li><li><strong>HBM3e 带宽</strong>: 3.35 TB/s = 每秒 3.35 × 10^12 字节</li><li><strong>每 FLOP 可用字节</strong>: 3.35 × 10^12 / 1.979 × 10^15 ≈ <strong>1.7 字节/FLOP</strong></li></ul><p>一个 FP8 matmul 需要: 每输出元素读 A 的 1 行 + B 的 1 列 = O(N) 个元素, 写 O(N) 个元素。如果 N 很大, <strong>带宽根本跟不上算力</strong>——这是为什么 FlashAttention 要通过 block-wise tiling 把数据块留在 SRAM 里循环用, 而不是反复读 HBM。HBM 3.35 TB/s 听起来很大, 但除以 1979 TFLOPS 后少得可怜。</p><p>把同样比例拉到 CPU 侧:</p><ul><li><strong>AMD Zen 5 core</strong>: 4 ALU + 3 AGU, 4GHz, 每周期可 issue 8 条微指令</li><li><strong>DDR5-5600 单通道</strong>: 44.8 GB/s = 每秒 4.48 × 10^10 字节</li><li><strong>每操作可用字节</strong>: 约 1.4 字节/操作 (假设 8 IPC × 4GHz = 32G ops/s)</li></ul><p>顺序访问 (row buffer hit) 时可以达到 ~40 GB/s, 但随机访问 (每次换 row → tRCD + tRP) 时吞吐只有 ~1.4 GB/s per channel (见 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §二)——<strong>实际的带宽可用率在随机 workload 下坍缩到标称的 3%</strong>。</p><h3 id="wall-驱动了哪些工程决策" tabindex="-1">Wall 驱动了哪些工程决策 <a class="header-anchor" href="#wall-驱动了哪些工程决策" aria-label="Permalink to &quot;Wall 驱动了哪些工程决策&quot;">​</a></h3><ul><li><strong>HBM (<a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §九)</strong>: 既然 DRAM 延迟降不下去, 就用 TSV 堆叠把内存物理搬到离计算 die 0.1mm 以内的距离 + 1024-bit 宽总线把带宽硬顶上去。<strong>代价是 $15-20/GB vs DDR5 的 $3-4/GB。</strong></li><li><strong>3D V-Cache (<a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §十)</strong>: 既然去 DRAM 太慢, 就在计算 die 正上方再焊一层 64MB SRAM。<strong>加 4 cycle 跨层延迟, 省掉 400 cycle 的 DRAM miss。</strong></li><li><strong>CXL 内存池化 (<a href="./../computer-arch/interconnects">interconnects.md</a> §三)</strong>: 既然 Memory Wall 导致很多服务器的 DRAM 闲置 (利用率 50-60%), 就用 CXL 把闲置内存动态分配给需要的节点。<strong>~300ns 的 CXL.mem 延迟比本机 DRAM 的 100ns 高一倍, 但比 swap/SSD 的 100µs 快 300 倍。</strong></li><li><strong>NVLink (<a href="./../computer-arch/interconnects">interconnects.md</a> §四)</strong>: 既然 PCIe 5.0 x16 = 64 GB/s 远不够 GPU all-reduce 的带宽需求, 就自建 7× 带宽的专用链路。<strong>NVLink 护城河的本质是 Memory Wall 护城河——没有 NVLink 就无法做 TP, 不做 TP 就无法训练大模型。</strong></li><li><strong>LSM Compaction (<a href="./../system-design/storage/wal-lsm-btree">wal-lsm-btree.md</a>)</strong>: Memory Wall 迫使 LSM-tree 以 MB 为单位做后台 compaction——不是&quot;这么做更优雅&quot;, 是&quot;不批量 IO 的话每次随机读 100µs, Level 4 → Level 5 的 compaction 跑一个月也跑不完&quot;。<strong>Compaction 的单位 (MB) 由 SSD 的带宽/延迟比决定。</strong></li><li><strong>Redis 集群 sizing (<a href="./../system-design/cache/multilevel">multilevel.md</a>)</strong>: Memory Wall 解释了为什么 Redis 集群的容量上限不是 RAM 大小, 而是&quot;单节点的网络带宽 ÷ 平均 key size&quot;。一台 25 Gbps 网卡的 Redis 节点, 对小 key (100B) 的理论 QPS 上限是 25Gbps / 8 / 100B ≈ 31M QPS (实际受单线程限制 ~100K), 对大 key (1MB) 的上限是 ~3K QPS。</li></ul><hr><h2 id="四、工程洞察-cache-的五边形通用模型" tabindex="-1">四、工程洞察: cache 的五边形通用模型 <a class="header-anchor" href="#四、工程洞察-cache-的五边形通用模型" aria-label="Permalink to &quot;四、工程洞察: cache 的五边形通用模型&quot;">​</a></h2><p>任何 cache 层都可以被这五个维度的参数完整描述:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         Hit/Miss 判定</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│  Key → 查找 → Value 或 MISS │</span></span>
<span class="line"><span>└─────────────────────────────┘</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>    ┌─────────┼─────────┐</span></span>
<span class="line"><span>    ▼         ▼         ▼</span></span>
<span class="line"><span>   命中      缺失       预取</span></span>
<span class="line"><span>  (1ns~ms) (惩罚延迟) (可选)</span></span>
<span class="line"><span>    │         │</span></span>
<span class="line"><span>    │    ┌────▼─────┐</span></span>
<span class="line"><span>    │    │ 块管理     │ ← 按什么粒度取/填? (64B / 4KB / object)</span></span>
<span class="line"><span>    │    │ 替换策略   │ ← 满了淘汰谁? (LRU / LFU / ARC / RRIP)</span></span>
<span class="line"><span>    │    │ 一致性协议 │ ← 多副本怎么同步? (MESI / Raft / purge)</span></span>
<span class="line"><span>    │    │ 写策略     │ ← write-through 还是 write-back?</span></span>
<span class="line"><span>    │    └───────────┘</span></span></code></pre></div><p><strong>所有 cache 层都是这个五边形的不同实例化。</strong> 硬件 cache 把这五行烧录在硅片上, OS page cache 把这五行实现在内核 C 代码里, Redis 把这五行实现在用户态 <code>server.c</code> 里, CDN 把这五行实现在边缘节点的反向代理 (NGINX/Varnish) 里。<strong>理解了这张五边形图, 你就理解了计算机系统中&quot;记忆&quot;的本质。</strong></p><h3 id="五维度在每一层的实例化对比" tabindex="-1">五维度在每一层的实例化对比 <a class="header-anchor" href="#五维度在每一层的实例化对比" aria-label="Permalink to &quot;五维度在每一层的实例化对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>L1 Cache (硬件)</th><th>OS Page Cache</th><th>InnoDB Buffer Pool</th><th>Redis LRU</th><th>CDN Edge</th></tr></thead><tbody><tr><td>Hit/Miss 判定</td><td>Tag 比较 (1 cycle)</td><td>Radix tree / 哈希查 page</td><td>Hash table (page_id → frame)</td><td>Hash table (key → robj)</td><td>URL + headers → cache key</td></tr><tr><td>块大小</td><td>64B (cache line)</td><td>4KB (page)</td><td>16KB (page, 可调)</td><td>Key-value (variable)</td><td>HTTP object (variable)</td></tr><tr><td>替换策略</td><td>PLRU / RRIP / BRRIP</td><td>双链表 LRU (active/inactive)</td><td>Midpoint LRU (5/8 split)</td><td>allkeys-lru / allkeys-lfu</td><td>LRU / cost-based</td></tr><tr><td>一致性协议</td><td>MESI/MOESI/MESIF (bus/dir)</td><td>无 (单 OS kernel)</td><td>WAL (crash recovery) + buffer pool mutex</td><td>主从 async replication</td><td>Purge / TTL-based invalidation</td></tr><tr><td>写策略</td><td>Write-back + write-allocate</td><td>Write-back (dirty page → 定期回写)</td><td>Write-back (dirty page → checkpoint/WAL)</td><td>Write-through (写同时更新 DB/cache)</td><td>源站写 → edge 被动失效或主动 purge</td></tr><tr><td>预取</td><td>Next-line / stride / AMPM</td><td>readahead (顺序访问检测)</td><td>Linear read-ahead (预取 64 pages)</td><td>无 (按需加载)</td><td>Pre-warm (主动推热资源到 edge)</td></tr></tbody></table><p>这张对比表是本章所有论点的物证。<strong>同构不是类比, 是严格的 engineering convergence: 面对相同的约束 (容量/延迟/成本之不可能三角), 不同层级的工程方案收敛到了同一组设计模式。</strong></p><hr><h2 id="五、预取与预热-另一个跨层同构" tabindex="-1">五、预取与预热: 另一个跨层同构 <a class="header-anchor" href="#五、预取与预热-另一个跨层同构" aria-label="Permalink to &quot;五、预取与预热: 另一个跨层同构&quot;">​</a></h2><p>cache 不只是&quot;被动地等人来查&quot;。每一层都有主动提前拉取数据的机制, 在硬件叫 <strong>prefetching</strong>, 在软件叫 <strong>cache warming / pre-warming</strong>:</p><table tabindex="0"><thead><tr><th>层级</th><th>预取/预热机制</th><th>原理</th></tr></thead><tbody><tr><td>L1/L2/L3 (硬件)</td><td>Next-line / Stride / AMPM prefetchers (<a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §十二)</td><td>检测访问模式, 提前发 miss 请求填 line</td></tr><tr><td>OS Page Cache</td><td>readahead (顺序访问检测): <code>posix_fadvise(POSIX_FADV_WILLNEED)</code></td><td>检测到顺序读 → 后台预读后续页面到 page cache</td></tr><tr><td>InnoDB Buffer Pool</td><td>Linear read-ahead: 连续访问 56 个 pages → 预取 64 pages</td><td>和硬件 next-line prefetch 逻辑完全一致</td></tr><tr><td>Redis</td><td>无内置 prefetch; 冷启动时用 <code>--rdb</code> 或 <code>DEBUG RELOAD</code> 从持久化文件恢复</td><td>恢复本质上是一次性大批量&quot;填 cache&quot;</td></tr><tr><td>CDN</td><td>Pre-warm: 主动推送热文件到 edge POP, 或 <code>stale-while-revalidate</code> 在后台刷新</td><td>等价于&quot;软件 prefetch&quot;: 预期会 miss 的对象提前拉</td></tr></tbody></table><p><strong>预取的本质矛盾</strong>: 预取太多 → 浪费带宽 + 污染 cache; 预取太少 → miss penalty 无法隐藏。硬件 Stride prefetcher 通过跟踪地址间距来区分&quot;该预取&quot;和&quot;不该预取&quot;的访问流; OS readahead 用 access pattern detection (顺序流的 sequential ratio 判断); CDN pre-warm 用业务先验 (即将上线的大促海报)。三种手段解决的是<strong>同一个带噪声的信号检测问题</strong>: 从历史访问模式中推断未来访问概率。</p><hr><h2 id="六、易错清单" tabindex="-1">六、易错清单 <a class="header-anchor" href="#六、易错清单" aria-label="Permalink to &quot;六、易错清单&quot;">​</a></h2><ol><li><p><strong>&quot;cache 就是快内存&quot;</strong>: cache 的本质不是&quot;快内存&quot;, 是&quot;小内存 + 淘汰算法 + 一致性协议&quot;。把 cache 当成&quot;更快的内存&quot;来用是初学者最常见的错误——实际上 cache 能加速你, 是因为你访问的数据满足时间/空间局部性。如果你用 cache 装随机访问的数据, cache 不但不会加速, 还会因为频繁淘汰和协议开销变得更慢 (见 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §十四 §2 false sharing, 以及 <a href="./../system-design/cache/failure-modes">failure-modes.md</a>)。</p></li><li><p><strong>&quot;多一层 cache 一定更快&quot;</strong>: 每一层 cache 都加一个 lookup 开销。L1 花了 1ns, L2 花了 4ns, L3 花了 12ns——加上去不是为了让你全走一遍, 是为了 miss 的时候不用直接摔到 100ns 的 DRAM。如果你在软件栈里加了一层 Redis, 但 90% 的请求都是 miss 还回源查 DB, 那你加的不是 cache 加速器, 是延迟累加器。<strong>cache hit rate &lt; 80% 的 cache 层应该被移除或重新设计。</strong></p></li><li><p><strong>&quot;一致性协议可以靠最终一致性省掉&quot;</strong>: MESI 的&quot;强一致&quot;代价是总线广播和 directory lookup。Paxos 的&quot;强一致&quot;代价是两轮 RPC + 多数派确认。所以你发明了&quot;最终一致性&quot;——Redis 主从异步复制, CDN TTL 过期后回源。但最终一致性不意味着&quot;没有一致性协议&quot;——它意味着<strong>你把&quot;不一致窗口&quot;的代价转移到了应用层</strong> (见 <a href="./../system-design/cache/failure-modes">failure-modes.md</a> §一-三)。缓存雪崩、穿透、击穿本质上都是&quot;一致性协议不够强&quot;时应用层爆炸的表现。</p></li><li><p><strong>&quot;替换策略不重要, LRU 够用了&quot;</strong>: 如果你的 workload 是固定 hot set (如社交网络的热门帖子), LRU 确实够用。但如果你的 workload 是混合的——90% 的流量来自 10% 的 key, 但每隔 10 分钟有一个批量任务扫过所有 key——LRU 会在扫描过程中把整个热点集合全部刷掉。这就是为什么 W-TinyLFU、ARC、BRRIP、midpoint insertion 要存在: <strong>它们保护的不是&quot;个别的热数据&quot;, 而是&quot;热点集合的结构完整性&quot;</strong>。</p></li><li><p><strong>&quot;Memory Wall 是硬件问题, 软件不用管&quot;</strong>: 正因为 Memory Wall 是物理性的 (光速限制物理距离 → 电容充放电速度限制 DRAM→ 成本限制 SRAM 面积), 软件才必须管。LSM-tree 选择顺序写而不是随机写、列存选择压缩 + late materialization 而不是行存、RocksDB 选择 block-aligned SSTable 而不是按行存——这些软件决策的根因全在 Memory Wall。不明白 DRAM 的 bank/row/column 结构 (<a href="./../computer-arch/memory-hierarchy">memory-hierarchy.md</a> §八), 你就不知道为什么 compaction 的 stride 要和 SSD page 对齐。</p></li><li><p><strong>&quot;TLB 跟我写应用没关系&quot;</strong>: 见 <a href="./../computer-arch/mmu-dma">mmu-dma.md</a> §4。一次 TLB miss 的成本是 ~400ns (4 次 DRAM 读做 page walk)。如果一个进程有 256MB working set, 用 4KB 页就需要 65,536 个页表项——远超任何 CPU 的 TLB 容量。用 HugePages (2MB) 则只需 128 个表项, 全部可装入 L2 TLB。PostgreSQL 和 JVM 的生产调优里, <code>huge_pages = on</code> 和 <code>-XX:+UseTransparentHugePages</code> 能带来 5-15% 的吞吐提升, 这本质上就是把 lookup structure 从&quot;TLB 装不下&quot;改成&quot;TLB 装得下&quot;——和调整 Redis 的 <code>maxmemory</code> 保证热数据集全在内存里是同一回事。</p></li></ol><hr><h2 id="七、这一章带走的东西" tabindex="-1">七、这一章带走的东西 <a class="header-anchor" href="#七、这一章带走的东西" aria-label="Permalink to &quot;七、这一章带走的东西&quot;">​</a></h2><ol><li><p><strong>整个计算机系统是一部递归的 cache 层次模型。</strong> 寄存器 → L1 → L2 → L3 → DRAM → SSD → 网络 → CDN 的每一层都服从同构的五边形模型: hit/miss 判定 → 按块传输 → 替换 → 一致性 → 写策略。</p></li><li><p><strong>MESI cache coherence ≈ 硬件尺度的 Paxos。</strong> 状态转换 (M→E→S→I vs Follower→Candidate→Leader)、排他权获取 (RFO vs Leader Election)、数据传播 (snoop multicast vs AppendEntries)、冲突仲裁 (总线仲裁 vs term number)——在硬件域和软件分布式域之间逐行对应。区别仅在于&quot;信道的可靠性&quot;: 铜互联不会丢包, UDP 会。</p></li><li><p><strong>TLB 是页表的 cache, Buffer Pool 是 B-tree 的 cache, <code>dcache</code> 是 inode 表的 cache。</strong> 这三个 lookup structure 的 cache 关系是完全同构的: 命中时 O(1) 返回映射, miss 时逐层遍历 → 把结果填入高速结构 → 重试命中。理解了这个模式, DNS、ARP table、路由表、LSM bloom filter——所有 lookup structure 的 cache 机制都统一了。</p></li><li><p><strong>HBM (宽总线 + TSV)、NVLink (多链路点对点)、RDMA (单边绕过 CPU) 是同一个工程模式:</strong> &quot;延迟降不下去, 就加宽通道、减薄协议栈、去仲裁——用并行和近邻克服物理极限。&quot;</p></li><li><p><strong>Memory Wall 是终极约束。</strong> 算力每年 55% 增长, 存储延迟每年 7% 改善。这个剪刀差驱动了 HBM、3D V-Cache、CXL 内存池化、NVLink、LSM compaction 策略、Redis 集群 sizing——从硅片到 CDN, 每一层工程决策的根因都归结到 Memory Wall。</p></li><li><p><strong>Master 一个 cache 层, 你就 master 了所有 cache 层。</strong> L1 cache 工程师转行做 Redis 调优、做 CDN 架构、做数据库 buffer pool 设计, 只需要翻译术语表:&quot;cache line&quot; → &quot;page&quot; → &quot;object&quot;, &quot;MESI&quot; → &quot;主从复制&quot; → &quot;purge propagation&quot;, &quot;write-back&quot; → &quot;dirty page flush&quot; → &quot;lazy invalidation&quot;。<strong>底层抽象是相同的, 上层只是实例化的参数差异。</strong></p></li></ol><hr><p>下一篇 → <a href="./runtime-semantics">5. 编程语言运行时: 四种实现语义</a></p>`,72)])])}const u=e(d,[["render",o]]);export{m as __pageData,u as default};
